    """Transform: 3s adjacent to 2s become 1s"""
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                # Check orthogonal neighbors for 2
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2:
                        result[r][c] = 1
                        break
    return result

