def transform(grid):
    """
    Rule discovered:
    1. 3 cells that have at least 2 orthogonal neighbors = 3 become 1
    2. 2 cells that become 1 (after checking rule above) mark 3 neighbors as 1
    3. 0 cells with 2 below them become 1
    """
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # First: 3 cells with 2+ orthogonal 3 neighbors become 1
    # (this also determines which 2s will become 1s)
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                # Count orthogonal 3 neighbors
                score = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3:
                        score += 1
                if score >= 2:
                    result[r][c] = 1

    # Second: 2 cells whose 3-value neighbor count is >= 2 become 1, and mark their orthogonal 3 neighbors as 1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                # Only check original neighbors with value 3
                threes = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3:
                        threes.append((nr, nc))
                if len(threes) >= 2:
                    result[r][c] = 1
                    for nr, nc in threes:
                        result[nr][nc] = 1

    # Third: 0 cells with 2 below become 1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                if 0 <= r+1 < h and grid[r+1][c] == 2:
                    result[r][c] = 1

    return result

