def transform(grid):
    """
    Transform rule based on demo 1 analysis:
    For each 2:
    - Cells at Manhattan distance 1 from 2 become 1
    - Cells at Manhattan distance 2 from 2 become 1 if they are 3
    - 2s surrounded by 3s become 1, otherwise stay 2
    """
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # First pass: identify 2s
    twos = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]

    # Second pass: for each 2, mark affected cells
    for tr, tc in twos:
        # Mark cells at distance 1 and 2
        for r in range(h):
            for c in range(w):
                dist = abs(r - tr) + abs(c - tc)
                if dist == 1:
                    # Manhattan distance 1 cells become 1
                    result[r][c] = 1
                elif dist == 2:
                    # Manhattan distance 2 cells become 1 if they're 3
                    if grid[r][c] == 3:
                        result[r][c] = 1

    # Third pass: handle the 2s themselves
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                # Check if surrounded by 3s
                score = 0
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 3:
                        score += 1
                # If 2 has at least 1 orthogonal 3, it becomes 1
                if score >= 1:
                    result[r][c] = 1
                else:
                    # Stay 2
                    pass

    return result

