def transform_v2(grid):
    """
    For each 2, create a diamond of 1s:
    - distance 0: 2 becomes 1 (always)
    - distance 1: becomes 1 always
    - distance 2: becomes 1 only if original was 3
    - distance 3: becomes 1 only if original was 3
    - distance 4: becomes 1 only if original was 3
    """
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Find all 2s and create their influence zones
    for tr, tc in [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]:
        for r in range(h):
            for c in range(w):
                dist = abs(r - tr) + abs(c - tc)
                if dist == 0:
                    result[r][c] = 1
                elif dist <= 2:
                    result[r][c] = 1
                # dist > 2: do nothing (original stays as-is)

    return result

