    """Returns (has_0, has_3) for beams going up/down from 2 at (r,c)"""
    has_0 = False
    has_3 = False

    # Check up
    for i in range(r-1, -1, -1):
        if grid[r][c] != 2:
            break
        if grid[i][c] == 1:
            if grid[i][c] in [1, 2]:  # 1s in output
                pass  # fell, no beam through
        if grid[i][c] == 1:
            if grid[i][c] == 3:
                has_3 = True
            elif grid[i][c] == 0:
                has_0 = True
            elif grid[i][c] == 2:
                pass
        else:
            break

    # Check down
    for i in range(r+1, len(grid)):
        if grid[i][c] == 1:
            if grid[i][c] in [1, 2]:
                pass
            if i+1, c in grid:
                if grid[i][c] == 3:
                    has_3 = True
                elif grid[i][c] == 0:
                    has_0 = True
        if grid[i][c] != 1:
            break

    return has_0, has_3

